import copy


def _decode_token(raw):
    out = []
    i = 0
    n = len(raw)
    while i < n:
        ch = raw[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError
            nxt = raw[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise ValueError
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError
    return [_decode_token(part) for part in pointer.split("/")[1:]]


def _parse_index(token, length, allow_end):
    if token == "0":
        is_zero = True
    else:
        if not token or token[0] < "1" or token[0] > "9":
            raise ValueError
        for ch in token[1:]:
            if ch < "0" or ch > "9":
                raise ValueError
        is_zero = False

    max_allowed = length if allow_end else length - 1
    if max_allowed < 0:
        raise ValueError

    if is_zero:
        return 0

    if len(token) > len(str(max_allowed)):
        raise ValueError

    idx = int(token)
    if idx > max_allowed:
        raise ValueError
    return idx


def _resolve_parent(document, tokens):
    node = document
    for token in tokens[:-1]:
        if isinstance(node, dict):
            if token not in node:
                raise ValueError
            node = node[token]
        elif isinstance(node, list):
            idx = _parse_index(token, len(node), False)
            node = node[idx]
        else:
            raise ValueError
    return node, tokens[-1]


def _add(document, tokens, value):
    if not tokens:
        return value

    parent, last = _resolve_parent(document, tokens)

    if isinstance(parent, dict):
        parent[last] = value
        return document

    if isinstance(parent, list):
        if last == "-":
            idx = len(parent)
        else:
            idx = _parse_index(last, len(parent), True)
        parent.insert(idx, value)
        return document

    raise ValueError


def _remove(document, tokens):
    if not tokens:
        raise ValueError

    parent, last = _resolve_parent(document, tokens)

    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError
        del parent[last]
        return document

    if isinstance(parent, list):
        idx = _parse_index(last, len(parent), False)
        del parent[idx]
        return document

    raise ValueError


def _replace(document, tokens, value):
    if not tokens:
        return value

    parent, last = _resolve_parent(document, tokens)

    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError
        parent[last] = value
        return document

    if isinstance(parent, list):
        idx = _parse_index(last, len(parent), False)
        parent[idx] = value
        return document

    raise ValueError


def _get(document, tokens):
    if not tokens:
        return document

    parent, last = _resolve_parent(document, tokens)

    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError
        return parent[last]

    if isinstance(parent, list):
        idx = _parse_index(last, len(parent), False)
        return parent[idx]

    raise ValueError


def _json_equal(a, b):
    a_bool = isinstance(a, bool)
    b_bool = isinstance(b, bool)
    if a_bool or b_bool:
        return a_bool and b_bool and a == b

    a_num = isinstance(a, (int, float))
    b_num = isinstance(b, (int, float))
    if a_num or b_num:
        return a_num and b_num and a == b

    if a is None or b is None:
        return a is None and b is None

    if isinstance(a, str) or isinstance(b, str):
        return isinstance(a, str) and isinstance(b, str) and a == b

    if isinstance(a, list) or isinstance(b, list):
        if not (isinstance(a, list) and isinstance(b, list)):
            return False
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    if isinstance(a, dict) or isinstance(b, dict):
        if not (isinstance(a, dict) and isinstance(b, dict)):
            return False
        if len(a) != len(b):
            return False
        for key, value in a.items():
            if key not in b:
                return False
            if not _json_equal(value, b[key]):
                return False
        return True

    return a == b


def _test(document, tokens, value):
    actual = _get(document, tokens)
    if not _json_equal(actual, value):
        raise ValueError
    return document


def _move(document, from_tokens, path_tokens):
    source_value = _get(document, from_tokens)

    n = len(from_tokens)
    if len(path_tokens) > n and path_tokens[:n] == from_tokens:
        raise ValueError

    if path_tokens == from_tokens:
        return document

    document = _remove(document, from_tokens)
    document = _add(document, path_tokens, source_value)
    return document


def _copy(document, from_tokens, path_tokens):
    source_value = _get(document, from_tokens)
    copied = copy.deepcopy(source_value)
    return _add(document, path_tokens, copied)


def apply_patch(document, operations: list[dict]):
    if not isinstance(operations, list):
        raise ValueError

    working = copy.deepcopy(document)

    for operation in operations:
        if not isinstance(operation, dict):
            raise ValueError
        if "op" not in operation or "path" not in operation:
            raise ValueError

        op_name = operation["op"]
        path = operation["path"]

        if not isinstance(op_name, str) or not isinstance(path, str):
            raise ValueError

        tokens = _parse_pointer(path)

        if op_name == "add":
            if "value" not in operation:
                raise ValueError
            value = copy.deepcopy(operation["value"])
            working = _add(working, tokens, value)

        elif op_name == "remove":
            working = _remove(working, tokens)

        elif op_name == "replace":
            if "value" not in operation:
                raise ValueError
            value = copy.deepcopy(operation["value"])
            working = _replace(working, tokens, value)

        elif op_name == "move":
            if "from" not in operation or not isinstance(operation["from"], str):
                raise ValueError
            from_tokens = _parse_pointer(operation["from"])
            working = _move(working, from_tokens, tokens)

        elif op_name == "copy":
            if "from" not in operation or not isinstance(operation["from"], str):
                raise ValueError
            from_tokens = _parse_pointer(operation["from"])
            working = _copy(working, from_tokens, tokens)

        elif op_name == "test":
            if "value" not in operation:
                raise ValueError
            working = _test(working, tokens, operation["value"])

        else:
            raise ValueError

    return working

class _SegmentMatcher:
    __slots__ = ('m', 'star_mask', 'any_mask', 'lit_masks', 'accept_bit', 'start_active')

    def __init__(self, tokens):
        m = len(tokens)
        self.m = m
        self.accept_bit = 1 << m
        star_mask = 0
        any_mask = 0
        lit_masks = {}
        for i, token in enumerate(tokens):
            kind = token[0]
            bit = 1 << i
            if kind == 0:
                star_mask |= bit
            elif kind == 1:
                any_mask |= bit
            else:
                ch = token[1]
                lit_masks[ch] = lit_masks.get(ch, 0) | bit
        self.star_mask = star_mask
        self.any_mask = any_mask
        self.lit_masks = lit_masks
        active = 1
        active |= (active & star_mask) << 1
        self.start_active = active

    def match(self, text):
        active = self.start_active
        star_mask = self.star_mask
        any_mask = self.any_mask
        lit_masks = self.lit_masks
        for ch in text:
            nxt = (active & star_mask) | ((active & (any_mask | lit_masks.get(ch, 0))) << 1)
            nxt |= (nxt & star_mask) << 1
            active = nxt
            if not active:
                return False
        return (active & self.accept_bit) != 0


def _parse_ordinary_segment(segment):
    tokens = []
    i = 0
    length = len(segment)
    while i < length:
        ch = segment[i]
        if ch == '\\':
            if i + 1 >= length:
                raise ValueError("trailing backslash in pattern segment")
            tokens.append((2, segment[i + 1]))
            i += 2
        elif ch == '*':
            if not tokens or tokens[-1][0] != 0:
                tokens.append((0, None))
            i += 1
        elif ch == '?':
            tokens.append((1, None))
            i += 1
        else:
            tokens.append((2, ch))
            i += 1
    return tuple(tokens)


def _parse_pattern(pattern):
    if pattern == "":
        return []
    if pattern[0] == '/' or pattern[-1] == '/' or '//' in pattern:
        raise ValueError("invalid pattern")

    atoms = []
    for segment in pattern.split('/'):
        if segment == "":
            raise ValueError("invalid pattern")
        if segment == "**":
            atoms.append(None)
        else:
            atoms.append(_parse_ordinary_segment(segment))

    collapsed = []
    for atom in atoms:
        if atom is None and collapsed and collapsed[-1] is None:
            continue
        collapsed.append(atom)
    return collapsed


def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        return path == ""

    atoms = _parse_pattern(pattern)

    if path == "":
        for atom in atoms:
            if atom is not None:
                return False
        return True

    path_segments = path.split('/')

    has_globstar = False
    for atom in atoms:
        if atom is None:
            has_globstar = True
            break

    if not has_globstar:
        if len(atoms) != len(path_segments):
            return False
        cache = {}
        for atom, segment in zip(atoms, path_segments):
            matcher = cache.get(atom)
            if matcher is None:
                matcher = _SegmentMatcher(atom)
                cache[atom] = matcher
            if not matcher.match(segment):
                return False
        return True

    m = len(atoms)
    globstar_mask = 0
    ordinary_mask = 0
    groups = {}
    matchers_by_index = [None] * m

    for i, atom in enumerate(atoms):
        bit = 1 << i
        if atom is None:
            globstar_mask |= bit
        else:
            ordinary_mask |= bit
            entry = groups.get(atom)
            if entry is None:
                groups[atom] = [bit, atom]
            else:
                entry[0] |= bit

    matcher_objects = {}
    groups_list = []
    for atom, entry in groups.items():
        matcher = _SegmentMatcher(atom)
        matcher_objects[atom] = matcher
        groups_list.append((entry[0], matcher))

    for i, atom in enumerate(atoms):
        if atom is not None:
            matchers_by_index[i] = matcher_objects[atom]

    active = 1
    active |= (active & globstar_mask) << 1

    cache = {}
    cache_limit = 1024

    for segment in path_segments:
        ordinary_active = active & ordinary_mask
        count = ordinary_active.bit_count()
        next_active = active & globstar_mask

        if count:
            cached = cache.get(segment)
            if cached is not None:
                next_active |= (active & cached) << 1
            elif count < len(groups_list):
                bits = ordinary_active
                next_ordinary = 0
                while bits:
                    lsb = bits & -bits
                    index = lsb.bit_length() - 1
                    bits ^= lsb
                    if matchers_by_index[index].match(segment):
                        next_ordinary |= lsb << 1
                next_active |= next_ordinary
            else:
                match_bits = 0
                for mask, matcher in groups_list:
                    if matcher.match(segment):
                        match_bits |= mask
                if len(cache) < cache_limit:
                    cache[segment] = match_bits
                next_active |= (active & match_bits) << 1

        next_active |= (next_active & globstar_mask) << 1
        active = next_active
        if not active:
            return False

    return ((active >> m) & 1) != 0

def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError
    parts = pointer.split("/")[1:]
    tokens = []
    for part in parts:
        out = []
        i = 0
        n = len(part)
        while i < n:
            ch = part[i]
            if ch == "~":
                if i + 1 >= n:
                    raise ValueError
                nxt = part[i + 1]
                if nxt == "0":
                    out.append("~")
                elif nxt == "1":
                    out.append("/")
                else:
                    raise ValueError
                i += 2
            else:
                out.append(ch)
                i += 1
        tokens.append("".join(out))
    return tokens


def _parse_array_index(token):
    if not isinstance(token, str):
        raise ValueError
    if token == "0":
        return 0
    if not token:
        raise ValueError
    first = token[0]
    if first < "1" or first > "9":
