    return int(token)


def _deepcopy_json(value):
    if not isinstance(value, (dict, list)):
        return value
    memo = {}

    def make(src):
        if isinstance(src, dict):
            return {}
        return []

    root = make(value)
    memo[id(value)] = root
    stack = [(value, root)]
    while stack:
        src, dst = stack.pop()
        if isinstance(src, dict):
            for k, v in src.items():
                if isinstance(v, (dict, list)):
                    vid = id(v)
                    if vid in memo:
                        dst[k] = memo[vid]
                    else:
                        nv = make(v)
                        memo[vid] = nv
                        dst[k] = nv
                        stack.append((v, nv))
                else:
                    dst[k] = v
        else:
            for v in src:
                if isinstance(v, (dict, list)):
                    vid = id(v)
                    if vid in memo:
                        dst.append(memo[vid])
                    else:
                        nv = make(v)
                        memo[vid] = nv
                        dst.append(nv)
                        stack.append((v, nv))
                else:
                    dst.append(v)
    return root


def _resolve_parent(root, tokens):
    current = root
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise ValueError
            current = current[token]
        elif isinstance(current, list):
            idx = _parse_array_index(token)
            if idx >= len(current):
                raise ValueError
            current = current[idx]
        else:
            raise ValueError
    return current


