import re

def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        return path == ""

    # Validate pattern structure
    if pattern.startswith('/') or pattern.endswith('/') or '//' in pattern:
        raise ValueError("Invalid pattern")
    raw_segments = pattern.split('/')
    for seg in raw_segments:
        if seg == "":
            raise ValueError("Invalid pattern")
        if seg.endswith('\\'):
            raise ValueError("Invalid pattern")

    # Parse all pattern segments
    pat = []
    for seg in raw_segments:
        if seg == '**':
            pat.append(('globstar', None))
        else:
            tokens = []
            literal_chars = []
            has_wild = False
            i = 0
            L = len(seg)
            while i < L:
                c = seg[i]
                if c == '\\':
                    ch = seg[i + 1]
                    tokens.append(('lit', ch))
                    literal_chars.append(ch)
                    i += 2
                elif c == '*':
                    has_wild = True
                    if not tokens or tokens[-1][0] != '*':
                        tokens.append(('*', None))
                    i += 1
                elif c == '?':
                    has_wild = True
                    tokens.append(('?', None))
                    i += 1
                else:
                    tokens.append(('lit', c))
                    literal_chars.append(c)
                    i += 1
            if not has_wild:
                pat.append(('literal', ''.join(literal_chars)))
            else:
                # Split tokens by '*' into chunks
                chunks = []
                current = []
                for tok in tokens:
                    if tok[0] == '*':
                        chunks.append(current)
                        current = []
                    else:
                        current.append(tok)
                chunks.append(current)

                # Precompile chunk matchers
                compiled_chunks = []
                for chunk in chunks:
                    if not chunk:
                        compiled_chunks.append(None)
                    else:
                        # Check if chunk has any '?'
                        has_q = any(t[0] == '?' for t in chunk)
                        if not has_q:
                            # literal string
                            s = ''.join(t[1] for t in chunk)
                            compiled_chunks.append(('lit', s, len(s)))
                        else:
                            # build regex
                            parts = []
                            for t in chunk:
                                if t[0] == 'lit':
                                    parts.append(re.escape(t[1]))
                                else:
                                    parts.append('.')
                            regex = re.compile(''.join(parts))
                            compiled_chunks.append(('re', regex, len(chunk)))
                starts_with_star = (tokens[0][0] == '*')
                ends_with_star = (tokens[-1][0] == '*')
                pat.append(('wild', (compiled_chunks, starts_with_star, ends_with_star)))

    # Path segments
    if path == "":
        path_segs = []
    else:
        path_segs = path.split('/')

    P = len(pat)
    S = len(path_segs)
    p = 0
    s = 0
    star_p = -1
    star_s = -1
    cache = {}

    def match_chunk_at(chunk_info, text, pos):
        kind = chunk_info[0]
        if kind == 'lit':
            s = chunk_info[1]
            return text.startswith(s, pos)
        else:
            regex = chunk_info[1]
            m = regex.match(text, pos)
            return m is not None

    def seg_match(pat_idx, s_idx):
        key = (pat_idx, s_idx)
        if key in cache:
            return cache[key]
        kind, data = pat[pat_idx]
        text = path_segs[s_idx]
        if kind == 'literal':
            res = (text == data)
        else:
            compiled_chunks, starts_with_star, ends_with_star = data
            N = len(text)
            pos = 0
            num_chunks = len(compiled_chunks)
            res = True
            for i, chunk in enumerate(compiled_chunks):
                if chunk is None:
                    continue
                is_first = (i == 0)
                is_last = (i == num_chunks - 1)
                if is_first and not starts_with_star:
                    if not match_chunk_at(chunk, text, pos):
                        res = False
                        break
                    pos += chunk[2]
                elif is_last and not ends_with_star:
                    L = chunk[2]
                    if N - L < pos:
                        res = False
                        break
                    if not match_chunk_at(chunk, text, N - L):
                        res = False
                        break
                    pos = N
                else:
                    kind2 = chunk[0]
                    if kind2 == 'lit':
                        sstr = chunk[1]
                        idx = text.find(sstr, pos)
                        if idx == -1:
                            res = False
                            break
                        pos = idx + len(sstr)
                    else:
                        regex = chunk[1]
                        m = regex.search(text, pos)
                        if m is None:
                            res = False
                            break
                        pos = m.end()
            cache[key] = res
            return res
        cache[key] = res
        return res

    while s < S:
        if p < P:
            kind = pat[p][0]
            if kind == 'globstar':
                star_p = p
                star_s = s
                p += 1
                continue
            else:
                if seg_match(p, s):
                    p += 1
                    s += 1
                    continue
        if star_p != -1:
            star_s += 1
            if star_s > S:
                return False
            s = star_s
            p = star_p + 1
        else:
            return False

    while p < P and pat[p][0] == 'globstar':
        p += 1
    return p == P
