class FrameParser:
    def __init__(self, max_size: int):
        if max_size < 0:
            raise ValueError("max_size must be non-negative")
        self.max_size = max_size
        self._buffer = bytearray()
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("FrameParser is poisoned")
        if self._finished:
            raise ValueError("FrameParser has already finished successfully")

        self._buffer.extend(chunk)

        buf = self._buffer
        total = len(buf)
        pos = 0
        frames: list[str] = []

        while True:
            remaining = total - pos
            if remaining < 4:
                break

            length = (
                (buf[pos] << 24)
                | (buf[pos + 1] << 16)
                | (buf[pos + 2] << 8)
                | buf[pos + 3]
            )

            if length > self.max_size:
                self._poisoned = True
                self._buffer.clear()
                raise ValueError("frame length exceeds max_size")

            if remaining - 4 < length:
                break

            body_start = pos + 4
            body_end = body_start + length
            body = bytes(buf[body_start:body_end])

            try:
                text = body.decode("utf-8")
            except UnicodeDecodeError:
                self._poisoned = True
                self._buffer.clear()
                raise ValueError("frame body is not valid UTF-8") from None

            frames.append(text)
            pos = body_end

        if pos:
            del buf[:pos]

        return frames

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("FrameParser is poisoned")
        if self._finished:
            return None

        if self._buffer:
            self._poisoned = True
            self._buffer.clear()
            raise ValueError("incomplete frame at finish")

        self._finished = True
        return None

def _is_int_not_bool(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _deep_equal(a, b):
    a_is_bool = isinstance(a, bool)
    b_is_bool = isinstance(b, bool)
    if a_is_bool or b_is_bool:
        return a_is_bool and b_is_bool and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False

        if (
            all(isinstance(k, str) for k in a)
            and all(isinstance(k, str) for k in b)
        ):
            for key, value_a in a.items():
                if key not in b or not _deep_equal(value_a, b[key]):
                    return False
            return True

        b_items = list(b.items())
        used = [False] * len(b_items)
        for key_a, value_a in a.items():
            found = False
            for i, (key_b, value_b) in enumerate(b_items):
                if not used[i] and _deep_equal(key_a, key_b) and _deep_equal(value_a, value_b):
                    used[i] = True
                    found = True
                    break
            if not found:
                return False
        return True

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_deep_equal(x, y) for x, y in zip(a, b))

    if isinstance(a, tuple) and isinstance(b, tuple):
        if len(a) != len(b):
            return False
        return all(_deep_equal(x, y) for x, y in zip(a, b))

    return type(a) is type(b) and a == b


def _exists(balances, account):
    try:
        return account in balances
    except TypeError:
        return False


def replay_ledger(initial: dict, events: list) -> dict:
    balances = dict(initial)
    seen = {}
    results = []

    for event in events:
        event_id = event["id"]

        if event_id in seen:
            if _deep_equal(event, seen[event_id]):
                status = "duplicate"
            else:
                status = "conflict"
            results.append({"id": event_id, "status": status})
            continue

        seen[event_id] = event

        moves = event.get("moves", [])
        expected = event.get("expected", {})
        valid = True

        if not isinstance(moves, list):
            valid = False
        else:
            for move in moves:
                if not isinstance(move, (list, tuple)) or len(move) != 3:
                    valid = False
                    break

                source, destination, amount = move

                if not _exists(balances, source) or not _exists(balances, destination):
                    valid = False
                    break
                if source == destination:
                    valid = False
                    break
                if not _is_int_not_bool(amount) or amount <= 0:
                    valid = False
                    break

        if valid:
            if not isinstance(expected, dict):
                valid = False
            else:
                for account, value in expected.items():
                    if not _exists(balances, account):
                        valid = False
                        break
                    if not _is_int_not_bool(value):
                        valid = False
                        break

        if not valid:
            results.append({"id": event_id, "status": "invalid"})
            continue

        guard_failed = False
        for account, value in expected.items():
            if balances[account] != value:
                guard_failed = True
                break

        if guard_failed:
            results.append({"id": event_id, "status": "guard"})
            continue

        applied_moves = []
        insufficient = False

        for source, destination, amount in moves:
            if balances[source] < amount:
                insufficient = True
                break

            balances[source] -= amount
            balances[destination] += amount
            applied_moves.append((source, destination, amount))

        if insufficient:
            for source, destination, amount in reversed(applied_moves):
                balances[source] += amount
                balances[destination] -= amount
            results.append({"id": event_id, "status": "insufficient"})
        else:
            results.append({"id": event_id, "status": "applied"})

    return {"balances": balances, "results": results}

