import heapq


def shortest_route(edges, start, goal):
    if start == goal:
        return {"cost": 0, "path": [start]}

    forward = {}
    reverse = {}
    for edge in edges:
        u = edge[0]
        v = edge[1]
        w = edge[2]
        forward.setdefault(u, []).append((v, w))
        reverse.setdefault(v, []).append((u, w))

    def dijkstra(adj, source):
        dist = {source: (0, 0)}
        heap = [(0, 0, source)]
        while heap:
            cost, hops, node = heapq.heappop(heap)
            if dist.get(node) != (cost, hops):
                continue
            for nxt, weight in adj.get(node, ()):
                new_cost = cost + weight
                new_hops = hops + 1
                old = dist.get(nxt)
                if old is None or (new_cost, new_hops) < old:
                    dist[nxt] = (new_cost, new_hops)
                    heapq.heappush(heap, (new_cost, new_hops, nxt))
        return dist

    dist_from_start = dijkstra(forward, start)
    if goal not in dist_from_start:
        return None

    total_cost, total_hops = dist_from_start[goal]
    dist_to_goal = dijkstra(reverse, goal)

    valid = set()
    for node, (c, h) in dist_from_start.items():
        suffix = dist_to_goal.get(node)
        if suffix is None:
            continue
        if c + suffix[0] == total_cost and h + suffix[1] == total_hops:
            valid.add(node)

    path = [start]
    current = start

    while current != goal:
        current_cost, current_hops = dist_from_start[current]
        best_next = None
        for nxt, weight in forward.get(current, ()):
            info = dist_from_start.get(nxt)
            if info is None:
                continue
            if info[0] == current_cost + weight and info[1] == current_hops + 1 and nxt in valid:
                if best_next is None or nxt < best_next:
                    best_next = nxt
        path.append(best_next)
        current = best_next

    return {"cost": total_cost, "path": path}
