def _canonical(value):
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("num", value)
    if isinstance(value, float):
        return ("num", value)
    if value is None:
        return ("none",)
    if isinstance(value, str):
        return ("str", value)
    if isinstance(value, list):
        return ("list", tuple(_canonical(item) for item in value))
    if isinstance(value, tuple):
        return ("tuple", tuple(_canonical(item) for item in value))
    if isinstance(value, dict):
        return ("dict", frozenset(
            (_canonical(key), _canonical(item)) for key, item in value.items()
        ))
    return ("other", type(value).__name__, repr(value))


def _is_int_not_bool(value):
    return isinstance(value, int) and not isinstance(value, bool)


def replay_ledger(initial, events):
    balances = dict(initial)
    seen = {}
    results = []

    for event in events:
        event_id = event["id"]

        if event_id in seen:
            if _canonical(event) == seen[event_id]:
                results.append({"id": event_id, "status": "duplicate"})
            else:
                results.append({"id": event_id, "status": "conflict"})
            continue

        seen[event_id] = _canonical(event)

        moves = event.get("moves", [])
        expected = event.get("expected", {})
        invalid = False

        if not isinstance(moves, list):
            invalid = True
        else:
            for move in moves:
                if not isinstance(move, list) or len(move) != 3:
                    invalid = True
                    break

                source, destination, amount = move

                if not isinstance(source, str) or not isinstance(destination, str):
                    invalid = True
                    break

                if source not in balances or destination not in balances:
                    invalid = True
                    break

                if source == destination:
                    invalid = True
                    break

                if not _is_int_not_bool(amount) or amount <= 0:
                    invalid = True
                    break

        if not invalid:
            if not isinstance(expected, dict):
                invalid = True
            else:
                for account, value in expected.items():
                    if not isinstance(account, str):
                        invalid = True
                        break

                    if account not in balances:
                        invalid = True
                        break

                    if not _is_int_not_bool(value):
                        invalid = True
                        break

        if invalid:
            status = "invalid"
        else:
            guard_failed = False
            for account, value in expected.items():
                if balances[account] != value:
                    guard_failed = True
                    break

            if guard_failed:
                status = "guard"
            else:
                tentative = dict(balances)
                ok = True

                for source, destination, amount in moves:
                    if tentative[source] < amount:
                        ok = False
                        break

                    tentative[source] -= amount
                    tentative[destination] += amount

                if ok:
                    balances = tentative
                    status = "applied"
                else:
                    status = "insufficient"

        results.append({"id": event_id, "status": status})

    return {"balances": balances, "results": results}

