import heapq

def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    adj = {}
    rev_adj = {}
    for edge in edges:
        u, v, w = edge
        adj.setdefault(u, []).append((v, w))
        rev_adj.setdefault(v, []).append((u, w))

    def dijkstra(source, graph):
        dist = {source: (0, 0)}
        heap = [(0, 0, source)]
        while heap:
            cost, hops, u = heapq.heappop(heap)
            if dist.get(u) != (cost, hops):
                continue
            for v, w in graph.get(u, ()):
                nc = cost + w
                nh = hops + 1
                if v not in dist or (nc, nh) < dist[v]:
                    dist[v] = (nc, nh)
                    heapq.heappush(heap, (nc, nh, v))
        return dist

    dist_start = dijkstra(start, adj)
    if goal not in dist_start:
        return None

    C, H = dist_start[goal]
    dist_goal = dijkstra(goal, rev_adj)

    opt_adj = {}
    for edge in edges:
        u, v, w = edge
        if u in dist_start and v in dist_goal:
            c1, h1 = dist_start[u]
            c2, h2 = dist_goal[v]
            if c1 + w + c2 == C and h1 + 1 + h2 == H:
                opt_adj.setdefault(u, set()).add(v)

    opt_rev = {}
    for u, vs in opt_adj.items():
        for v in vs:
            opt_rev.setdefault(v, set()).add(u)

    can_reach = {goal}
    stack = [goal]
    while stack:
        v = stack.pop()
        for u in opt_rev.get(v, ()):
            if u not in can_reach:
                can_reach.add(u)
                stack.append(u)

    path = [start]
    cur = start
    while cur != goal:
        candidates = [v for v in opt_adj.get(cur, ()) if v in can_reach]
        if not candidates:
            return None
        nxt = min(candidates)
        path.append(nxt)
        cur = nxt

    return {"cost": C, "path": path}

