class FrameParser:
    def __init__(self, max_size: int) -> None:
        self.max_size = max_size
        self._buffer = bytearray()
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            raise ValueError("parser has already been finished")

        self._buffer.extend(chunk)

        frames: list[str] = []
        pos = 0
        total = len(self._buffer)

        while total - pos >= 4:
            length = int.from_bytes(self._buffer[pos:pos + 4], "big")

            if length > self.max_size:
                self._poisoned = True
                raise ValueError("frame body length exceeds max_size")

            end = pos + 4 + length
            if end > total:
                break

            try:
                text = self._buffer[pos + 4:end].decode("utf-8")
            except UnicodeDecodeError as exc:
                self._poisoned = True
                raise ValueError("frame body is not valid UTF-8") from exc

            frames.append(text)
            pos = end

        if pos:
            del self._buffer[:pos]

        return frames

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            return None
        if self._buffer:
            self._poisoned = True
            raise ValueError("incomplete frame at finish")

        self._finished = True
        return None

class FrameParser:
    def __init__(self, max_size: int):
        if max_size < 0:
            raise ValueError("max_size must be non-negative")
        self._max_size = max_size
        self._buf = bytearray()
        self._pos = 0
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            raise ValueError("parser is finished")

        self._buf.extend(chunk)
        out: list[str] = []
        pos = self._pos
        buf = self._buf

        try:
            while True:
                if len(buf) - pos < 4:
                    break

                n = int.from_bytes(buf[pos:pos + 4], "big")
                if n > self._max_size:
                    raise ValueError("frame too large")

                if len(buf) - pos < 4 + n:
                    break

                body_start = pos + 4
                body_end = body_start + n
                body = bytes(buf[body_start:body_end])
                out.append(body.decode("utf-8"))
                pos = body_end
        except Exception:
            self._poisoned = True
            raise

        if pos:
            del buf[:pos]
            pos = 0

        self._pos = pos
        return out

