        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            return None

        if len(self._buf) - self._pos > 0:
            self._poisoned = True
            raise ValueError("partial frame at finish")

        self._finished = True
        self._buf.clear()
        self._pos = 0
        return None

