def _parse_decimal(s):
    if not isinstance(s, str):
        s = str(s)
    s = s.strip()
    if s.startswith('+'):
        s = s[1:]
    if '.' in s:
        whole, frac = s.split('.', 1)
    else:
        whole, frac = s, ''
    if whole == '':
        whole = '0'
    digits = whole + frac
    if digits == '':
        num = 0
    else:
        num = int(digits)
    den = 10 ** len(frac)
    return num, den


def _round_half_up(num, den):
    q, r = divmod(num, den)
    if 2 * r >= den:
        q += 1
    return q


def _fmt(cents):
    return f"{cents // 100}.{cents % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    n = len(items)
    grosses = []
    taxables = []

    for item in items:
        unit_num, unit_den = _parse_decimal(item["unit"])
        qty = item["qty"]
        gross_cents = _round_half_up(unit_num * qty * 100, unit_den)
        grosses.append(gross_cents)
        taxables.append(bool(item["taxable"]))

    subtotal = sum(grosses)

    coupon_num, coupon_den = _parse_decimal(coupon)
    discount_total = _round_half_up(coupon_num * 100, coupon_den)
    if discount_total > subtotal:
        discount_total = subtotal

    if subtotal == 0:
        discounts = [0] * n
    else:
        base = [0] * n
        rems = [0] * n

        for i, g in enumerate(grosses):
            if g > 0:
                q, r = divmod(discount_total * g, subtotal)
                base[i] = q
                rems[i] = r

        remaining = discount_total - sum(base)
        if remaining > 0:
            order = sorted(
                (i for i, g in enumerate(grosses) if g > 0),
                key=lambda i: (-rems[i], i),
            )
            for i in order[:remaining]:
                base[i] += 1

        discounts = base

    rate_num, rate_den = _parse_decimal(tax_rate)

    lines = []
    total_net = 0
    total_tax = 0
    total_discount = 0

    for i in range(n):
        gross = grosses[i]
        discount = discounts[i]
        net = gross - discount

        if taxables[i]:
            tax = _round_half_up(net * rate_num, rate_den)
        else:
            tax = 0

        total = net + tax

        lines.append({
            "gross": _fmt(gross),
            "discount": _fmt(discount),
            "net": _fmt(net),
            "tax": _fmt(tax),
            "total": _fmt(total),
        })

        total_net += net
        total_tax += tax
        total_discount += discount

    return {
        "lines": lines,
        "subtotal": _fmt(subtotal),
        "discount": _fmt(total_discount),
        "net": _fmt(total_net),
        "tax": _fmt(total_tax),
        "total": _fmt(total_net + total_tax),
    }

