import copy
import math


def _canonical(value):
    if value is None:
        return ("none",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("num", value)
    if isinstance(value, float):
        if math.isnan(value):
            return ("nan",)
        return ("num", value)
    if isinstance(value, str):
        return ("str", value)
    if isinstance(value, (list, tuple)):
        return ("list", tuple(_canonical(item) for item in value))
    if isinstance(value, dict):
        return (
            "dict",
            tuple(sorted((key, _canonical(item)) for key, item in value.items())),
        )
    return ("other", type(value).__name__, repr(value))


def _tiebreak(value):
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, int(value))
    if isinstance(value, int):
        return (2, value)
    if isinstance(value, float):
        if math.isnan(value):
            return (3, "nan")
        return (4, value)
    if isinstance(value, str):
        return (5, value)
    if isinstance(value, (list, tuple)):
        return (6, tuple(_tiebreak(item) for item in value))
    if isinstance(value, dict):
        return (
            7,
            tuple(sorted((key, _tiebreak(item)) for key, item in value.items())),
        )
    return (8, type(value).__name__, repr(value))


def resolve_records(events):
    unique = {}

    for event in events:
        event_id = event["id"]
        canon = _canonical(event)

        if event_id not in unique:
            unique[event_id] = (canon, event)
            continue

        previous_canon, previous_event = unique[event_id]
        if previous_canon != canon:
            raise ValueError("conflicting duplicate event id")

        if _tiebreak(event) < _tiebreak(previous_event):
            unique[event_id] = (canon, event)

    records = [event for _, event in unique.values()]
    records.sort(
        key=lambda event: (event["ts"], event["actor"], event["id"]),
        reverse=True,
    )

    claimed = set()
    values = {}
    tombstone_keys = set()
    accepted = []
    rejected = []

    for event in records:
        event_id = event["id"]
        writes = event["writes"]
        keys = list(writes.keys())

        if any(key in claimed for key in keys):
            rejected.append(event_id)
            continue

        accepted.append(event_id)

        for key in keys:
            claimed.add(key)
            value = writes[key]
            if value is None:
                tombstone_keys.add(key)
            else:
                values[key] = copy.deepcopy(value)

    tombstones = sorted(tombstone_keys)
    values = {key: values[key] for key in sorted(values)}

    return {
        "values": values,
        "tombstones": tombstones,
        "accepted": accepted,
        "rejected": rejected,
    }
