import heapq

def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    nodes = {start, goal}
    for e in edges:
        nodes.add(e[0])
        nodes.add(e[1])

    adj = {node: [] for node in nodes}
    for e in edges:
        u, v, w = e[0], e[1], e[2]
        adj[u].append((v, w))

    INF = float("inf")
    dist = {node: INF for node in nodes}
    hops = {node: INF for node in nodes}

    dist[start] = 0
    hops[start] = 0
    heap = [(0, 0, start)]

    while heap:
        d, h, u = heapq.heappop(heap)
        if d != dist[u] or h != hops[u]:
            continue

        for v, w in adj[u]:
            nd = d + w
            nh = h + 1
            if nd < dist[v] or (nd == dist[v] and nh < hops[v]):
                dist[v] = nd
                hops[v] = nh
                heapq.heappush(heap, (nd, nh, v))

    if dist[goal] == INF:
        return None

    valid_adj = {node: [] for node in nodes}
    rev_valid = {node: [] for node in nodes}

    for e in edges:
        u, v, w = e[0], e[1], e[2]
        if dist[u] != INF and dist[v] != INF:
            if dist[v] == dist[u] + w and hops[v] == hops[u] + 1:
                valid_adj[u].append(v)
                rev_valid[v].append(u)

    good = {goal}
    stack = [goal]

    while stack:
        v = stack.pop()
        for u in rev_valid[v]:
            if u not in good:
                good.add(u)
                stack.append(u)

    path = [start]
    cur = start

    for _ in range(hops[goal]):
        best = None
        for v in valid_adj[cur]:
            if v in good and (best is None or v < best):
                best = v

        if best is None:
            return None

        path.append(best)
        cur = best

    return {"cost": dist[goal], "path": path}

import codecs


class SSEParser:
    def __init__(self) -> None:
        self._decoder = codecs.getincrementaldecoder("utf-8")("replace")
        self._bom_processed = False
        self._line_buf: list[str] = []
        self._swallow_lf = False
        self._data_lines: list[str] = []
        self._event = ""
        self._id = ""
        self._retry: int | None = None
        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")

        events: list[dict] = []
        text = self._decoder.decode(chunk, final=False)
        self._consume_text(text, events)
        return events

    def finish(self) -> list[dict]:
        if self._finished:
            return []

        self._finished = True
        events: list[dict] = []

        text = self._decoder.decode(b"", final=True)
        self._consume_text(text, events)

        if self._line_buf:
            line = "".join(self._line_buf)
            self._line_buf.clear()
            self._process_line(line)

        return events

    def _consume_text(self, text: str, events: list[dict]) -> None:
        if text and not self._bom_processed:
            self._bom_processed = True
            if text[0] == "\ufeff":
                text = text[1:]

        for ch in text:
            if ch == "\n":
                if self._swallow_lf:
                    self._swallow_lf = False
                else:
                    self._end_line(events)
            elif ch == "\r":
                self._swallow_lf = True
                self._end_line(events)
            else:
                self._swallow_lf = False
                self._line_buf.append(ch)

    def _end_line(self, events: list[dict]) -> None:
        line = "".join(self._line_buf)
        self._line_buf.clear()

        if line == "":
            if self._data_lines:
                data = "\n".join(self._data_lines)
                event = self._event if self._event != "" else "message"
                events.append(
                    {
                        "event": event,
                        "data": data,
                        "id": self._id,
                        "retry": self._retry,
                    }
                )

            self._data_lines.clear()
            self._event = ""
        else:
            self._process_line(line)

    def _process_line(self, line: str) -> None:
        if line.startswith(":"):
            return

        idx = line.find(":")
        if idx == -1:
            name = line
            value = ""
        else:
            name = line[:idx]
            value = line[idx + 1 :]
            if value.startswith(" "):
                value = value[1:]

        if name == "data":
            self._data_lines.append(value)
        elif name == "event":
            self._event = value
        elif name == "id":
            if "\x00" not in value:
                self._id = value
        elif name == "retry":
            if self._is_ascii_digits(value):
                self._retry = self._parse_decimal(value)

    @staticmethod
    def _is_ascii_digits(value: str) -> bool:
        if not value:
            return False
        for ch in value:
            if ch < "0" or ch > "9":
                return False
        return True

    @staticmethod
    def _parse_decimal(value: str) -> int:
        try:
            return int(value)
        except ValueError:
            pass

        result = 0
        n = len(value)
        i = 0
        first = n % 9

        if first:
            result = int(value[:first])
            i = first

        while i < n:
            chunk = value[i : i + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
            i += 9

        return result

