                    self._line = []
                    event = self._process_line(line)
                    if event is not None:
                        events.append(event)
            else:
                self._last_was_cr = False
                self._line.append(ch)

        return events

    def _process_line(self, line: str):
        if line == "":
            if self._data:
                event_name = self._event if self._event != "" else "message"
                data_value = "\n".join(self._data)
                event = {
                    "event": event_name,
                    "data": data_value,
                    "id": self._id,
                    "retry": self._retry,
                }
            else:
                event = None

            self._data = []
            self._event = ""
            return event

        if line.startswith(":"):
            return None

        colon = line.find(":")
        if colon == -1:
            field = line
            value = ""
        else:
            field = line[:colon]
            value = line[colon + 1:]

        if value.startswith(" "):
            value = value[1:]

        if field == "data":
            self._data.append(value)
        elif field == "event":
            self._event = value
        elif field == "id":
            if "\x00" not in value:
                self._id = value
        elif field == "retry":
            if value and all("0" <= ch <= "9" for ch in value):
                self._retry = self._parse_retry(value)

        return None

    @staticmethod
    def _parse_retry(value: str) -> int:
        result = 0
        n = len(value)
        first = n % 9
        i = 0

        if first:
            result = int(value[:first])
            i = first

        while i < n:
            result = result * 1000000000 + int(value[i:i + 9])
            i += 9

        return result
