import copy


def apply_patch(document, operations):
    result = copy.deepcopy(document)

    if not isinstance(operations, list):
        raise ValueError("operations must be a list")

    for operation in operations:
        if not isinstance(operation, dict):
            raise ValueError("operation must be an object")
        if "op" not in operation:
            raise ValueError("missing op")

        op = operation["op"]

        if op == "add":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _add(result, path, operation["value"])
        elif op == "remove":
            _require_keys(operation, ("path",))
            path = _parse_pointer(operation["path"])
            result = _remove(result, path)
        elif op == "replace":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _replace(result, path, operation["value"])
        elif op == "move":
            _require_keys(operation, ("path", "from"))
            source = _parse_pointer(operation["from"])
            destination = _parse_pointer(operation["path"])
            result = _move(result, source, destination)
        elif op == "copy":
            _require_keys(operation, ("path", "from"))
            source = _parse_pointer(operation["from"])
            destination = _parse_pointer(operation["path"])
            result = _copy(result, source, destination)
        elif op == "test":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _test(result, path, operation["value"])
        else:
            raise ValueError("unknown operation")

    return result


