def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")

    if pointer == "":
        return []

    if not pointer.startswith("/"):
        raise ValueError("invalid pointer")

    tokens = []
    for raw_token in pointer[1:].split("/"):
        decoded = []
        i = 0
        while i < len(raw_token):
            ch = raw_token[i]
            if ch == "~":
                if i + 1 >= len(raw_token):
                    raise ValueError("invalid tilde escape")
                nxt = raw_token[i + 1]
                if nxt == "0":
                    decoded.append("~")
                elif nxt == "1":
                    decoded.append("/")
                else:
                    raise ValueError("invalid tilde escape")
                i += 2
            else:
                decoded.append(ch)
                i += 1
        tokens.append("".join(decoded))

    return tokens


def _parse_array_index(token):
    if token == "0":
        return 0
    if not token:
        raise ValueError("invalid array index")

    first = token[0]
    if first < "1" or first > "9":
        raise ValueError("invalid array index")

    for ch in token[1:]:
        if ch < "0" or ch > "9":
            raise ValueError("invalid array index")

    return int(token)


def _step(container, token):
    if isinstance(container, list):
        if token == "-":
            raise ValueError("invalid array index")
        index = _parse_array_index(token)
        if index >= len(container):
            raise ValueError("array index out of range")
        return container[index]

    if isinstance(container, dict):
        if token not in container:
            raise ValueError("missing target")
        return container[token]

    raise ValueError("cannot traverse scalar")


