    current = root
    for token in tokens:
        current = _step(current, token)
    return current


def _get_parent(root, tokens):
    current = root
    for token in tokens[:-1]:
        current = _step(current, token)
    return current


def _add(root, tokens, value):
    if not tokens:
        return copy.deepcopy(value)

    parent = _get_parent(root, tokens)
    last = tokens[-1]

    if isinstance(parent, list):
        if last == "-":
            parent.append(copy.deepcopy(value))
        else:
            index = _parse_array_index(last)
            if index > len(parent):
                raise ValueError("array index out of range")
            parent.insert(index, copy.deepcopy(value))
