    else:
        raise ValueError("cannot add to scalar")

    return root


def _remove(root, tokens):
    if not tokens:
        raise ValueError("cannot remove root")

    parent = _get_parent(root, tokens)
    last = tokens[-1]

    if isinstance(parent, list):
        if last == "-":
            raise ValueError("invalid array index")
        index = _parse_array_index(last)
        if index >= len(parent):
            raise ValueError("array index out of range")
        del parent[index]
    elif isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing target")
        del parent[last]
