def _parse_decimal(s: str) -> tuple[int, int]:
    s = s.strip()
    if s.startswith('+'):
        s = s[1:]
    if '.' in s:
        whole, frac = s.split('.', 1)
    else:
        whole, frac = s, ''
    if whole == '':
        whole = '0'
    digits = whole + frac
    num = int(digits) if digits else 0
    den = 10 ** len(frac)
    return num, den


def _round_half_up_ratio(num: int, den: int) -> int:
    return (2 * num + den) // (2 * den)


def _fmt(cents: int) -> str:
    return f"{cents // 100}.{cents % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    n = len(items)

    grosses = [0] * n
    for i, item in enumerate(items):
        unit_num, unit_den = _parse_decimal(item["unit"])
        qty = int(item["qty"])
        grosses[i] = _round_half_up_ratio(unit_num * qty * 100, unit_den)

    subtotal = sum(grosses)

    coupon_num, coupon_den = _parse_decimal(coupon)
    discount_total = _round_half_up_ratio(coupon_num * 100, coupon_den)
    if discount_total > subtotal:
        discount_total = subtotal

    discounts = [0] * n
    if subtotal > 0 and discount_total > 0:
        remainders = [0] * n
        allocated = 0

        for i, gross in enumerate(grosses):
            if gross > 0:
                q, r = divmod(discount_total * gross, subtotal)
                discounts[i] = q
                remainders[i] = r
                allocated += q

        remaining = discount_total - allocated
        if remaining:
            order = sorted(
                (i for i, gross in enumerate(grosses) if gross > 0),
                key=lambda i: (-remainders[i], i),
            )
            for i in order[:remaining]:
                discounts[i] += 1

    tax_num, tax_den = _parse_decimal(tax_rate)

    lines = []
    total_net = 0
    total_tax = 0

    for i, item in enumerate(items):
        gross = grosses[i]
        discount = discounts[i]
        net = gross - discount

        if item["taxable"]:
            tax = _round_half_up_ratio(net * tax_num, tax_den)
        else:
            tax = 0

        total_net += net
        total_tax += tax

        lines.append({
            "gross": _fmt(gross),
            "discount": _fmt(discount),
            "net": _fmt(net),
            "tax": _fmt(tax),
            "total": _fmt(net + tax),
        })

    return {
        "lines": lines,
        "subtotal": _fmt(subtotal),
        "discount": _fmt(discount_total),
        "net": _fmt(total_net),
        "tax": _fmt(total_tax),
        "total": _fmt(total_net + total_tax),
    }

import math


def _signature(value):
    if value is None:
        return ("none",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("number", value, 1)
    if isinstance(value, float):
        if math.isnan(value):
            return ("number", "nan")
        if math.isinf(value):
            return ("number", "inf" if value > 0 else "-inf")
        numerator, denominator = value.as_integer_ratio()
        return ("number", numerator, denominator)
    if isinstance(value, str):
        return ("string", value)
    if isinstance(value, list):
        return ("list", tuple(_signature(item) for item in value))
    if isinstance(value, dict):
        return (
            "dict",
            tuple((key, _signature(value[key])) for key in sorted(value)),
        )
    return ("other", type(value).__name__, repr(value))


def _copy_json_value(value):
    if isinstance(value, dict):
        return {key: _copy_json_value(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [_copy_json_value(item) for item in value]
    return value


def resolve_records(events: list[dict]) -> dict:
    unique_events = {}

    for event in events:
        event_id = event["id"]
        signature = _signature(event)

        if event_id in unique_events:
            if unique_events[event_id][0] != signature:
                raise ValueError("conflicting duplicate event id")
        else:
            unique_events[event_id] = (signature, event)

    ranked_events = sorted(
        unique_events.values(),
        key=lambda pair: (
            pair[1]["ts"],
            pair[1]["actor"],
            pair[1]["id"],
        ),
        reverse=True,
    )

    claimed_keys = set()
    values = {}
    tombstone_keys = set()
    accepted = []
    rejected = []

    for _, event in ranked_events:
        event_id = event["id"]
        writes = event["writes"]

        if any(key in claimed_keys for key in writes):
            rejected.append(event_id)
            continue

        accepted.append(event_id)

        for key, value in writes.items():
            claimed_keys.add(key)
            if value is None:
                tombstone_keys.add(key)
            else:
                values[key] = _copy_json_value(value)

    ordered_values = {key: values[key] for key in sorted(values)}

    return {
        "values": ordered_values,
        "tombstones": sorted(tombstone_keys),
        "accepted": accepted,
        "rejected": rejected,
    }

