        if event_id in seen:
            if seen[event_id][0] != signature:
                raise ValueError("conflicting payload for event id")
        else:
            seen[event_id] = (signature, event)

    ranked_events = sorted(
        seen.values(),
        key=lambda pair: (
            pair[1]["ts"],
            pair[1]["actor"],
            pair[1]["id"],
        ),
        reverse=True,
    )

    claimed_keys = set()
    values = {}
    tombstone_keys = set()
    accepted = []
    rejected = []

    for _, event in ranked_events:
        event_id = event["id"]
        writes = event["writes"]

        has_claimed_key = False
        for key in writes:
            if key in claimed_keys:
                has_claimed_key = True
                break

        if has_claimed_key:
            rejected.append(event_id)
            continue

        accepted.append(event_id)

        for key in writes:
            value = writes[key]
            claimed_keys.add(key)
            if value is None:
                tombstone_keys.add(key)
            else:
                values[key] = _copy_value(value)

    return {
        "values": {key: values[key] for key in sorted(values)},
        "tombstones": sorted(tombstone_keys),
        "accepted": accepted,
        "rejected": rejected,
    }

