import copy
import json


def _json_equal(a, b):
    stack = [(a, b)]
    while stack:
        x, y = stack.pop()

        if isinstance(x, bool) or isinstance(y, bool):
            if not (isinstance(x, bool) and isinstance(y, bool) and x == y):
                return False
            continue

        if x is None or y is None:
            if not (x is None and y is None):
                return False
            continue

        if isinstance(x, (int, float)) and isinstance(y, (int, float)):
            if x != y:
                return False
            continue

        if isinstance(x, str) and isinstance(y, str):
            if x != y:
                return False
            continue

        if isinstance(x, list) and isinstance(y, list):
            if len(x) != len(y):
                return False
            stack.extend(zip(x, y))
            continue

        if isinstance(x, dict) and isinstance(y, dict):
            if len(x) != len(y):
                return False
            for k, v in x.items():
                if k not in y:
                    return False
                stack.append((v, y[k]))
            continue

        if type(x) is not type(y) or x != y:
            return False

    return True


def _canonical(event):
    return json.dumps(
        event,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )


def _copy_json(value):
    if value is None or isinstance(value, (bool, int, float, str)):
        return value

    if isinstance(value, list):
        root = []
    elif isinstance(value, dict):
        root = {}
    else:
        return copy.deepcopy(value)

    stack = [(value, root)]
    while stack:
        src, dst = stack.pop()

        if isinstance(src, list):
            for item in src:
                if isinstance(item, list):
                    new = []
                    dst.append(new)
                    stack.append((item, new))
                elif isinstance(item, dict):
                    new = {}
                    dst.append(new)
                    stack.append((item, new))
                else:
                    dst.append(item)

        elif isinstance(src, dict):
            for k, item in sorted(src.items(), key=lambda kv: kv[0]):
                if isinstance(item, list):
                    new = []
                    dst[k] = new
                    stack.append((item, new))
                elif isinstance(item, dict):
                    new = {}
                    dst[k] = new
                    stack.append((item, new))
                else:
                    dst[k] = item

    return root


def resolve_records(events):
    seen = {}

    for event in events:
        eid = event["id"]
        if eid in seen:
            if not _json_equal(seen[eid], event):
                raise ValueError("conflicting duplicate event id")
            if _canonical(event) < _canonical(seen[eid]):
                seen[eid] = event
        else:
            seen[eid] = event

    ordered = sorted(
        seen.values(),
        key=lambda e: (e["ts"], e["actor"], e["id"]),
        reverse=True,
    )

    claimed = set()
    values = {}
    tombstone_keys = []
    accepted = []
    rejected = []

    for event in ordered:
        eid = event["id"]
        writes = event["writes"]

        if any(k in claimed for k in writes):
            rejected.append(eid)
            continue

        accepted.append(eid)

        for k, v in writes.items():
            claimed.add(k)
            if v is None:
                tombstone_keys.append(k)
            else:
                values[k] = _copy_json(v)

    final_values = {k: values[k] for k in sorted(values)}

    return {
        "values": final_values,
        "tombstones": sorted(tombstone_keys),
        "accepted": accepted,
        "rejected": rejected,
    }

from collections import OrderedDict
import heapq

def run_cache(capacity: int, operations: list[dict]) -> list:
    entries = OrderedDict()
    expiry_heap = []
    results = []
    cap = capacity

    def purge(now: int) -> None:
        while expiry_heap and expiry_heap[0][0] <= now:
            expires_at, key = heapq.heappop(expiry_heap)
            item = entries.get(key)
            if item is not None and item[1] == expires_at:
                del entries[key]

    for operation in operations:
        t = operation["t"]
        purge(t)

        kind = operation["op"]

        if kind == "put":
            key = operation["key"]
            value = operation["value"]
            ttl = operation["ttl"]

            if ttl <= 0 or cap == 0:
                if key in entries:
                    del entries[key]
                results.append(None)
            else:
                expires_at = t + ttl
                if key in entries:
                    del entries[key]
                entries[key] = (value, expires_at)
                heapq.heappush(expiry_heap, (expires_at, key))

                while len(entries) > cap:
                    entries.popitem(last=False)

                results.append(None)

        elif kind == "get":
            key = operation["key"]
            item = entries.get(key)
            if item is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(item[0])

        elif kind == "delete":
            key = operation["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)

        elif kind == "items":
            results.append([[key, item[0]] for key, item in entries.items()])

        elif kind == "resize":
            cap = operation["capacity"]
            while len(entries) > cap:
                entries.popitem(last=False)
            results.append(None)

    return results

