from collections import deque


def schedule_jobs(jobs: list[dict], workers: int) -> list[dict]:
    if not jobs:
        return []

    n = len(jobs)
    ids = [None] * n
    durations = [0] * n
    priorities = [0] * n
    id_to_index = {}

    for i, job in enumerate(jobs):
        jid = job["id"]
        if jid in id_to_index:
            raise ValueError("duplicate job id")
        id_to_index[jid] = i
        ids[i] = jid
        durations[i] = job["duration"]
        priorities[i] = job["priority"]

    deps = [None] * n
    dependents = [[] for _ in range(n)]
    indegree = [0] * n

    for i, job in enumerate(jobs):
        jid = ids[i]
        seen = set()
        unique_deps = []

        for dep in job["deps"]:
            if dep not in id_to_index:
                raise ValueError("unknown dependency")
            if dep == jid:
                raise ValueError("self dependency")
            if dep not in seen:
                seen.add(dep)
                unique_deps.append(dep)

        deps[i] = unique_deps
        indegree[i] = len(unique_deps)
        for dep in unique_deps:
            dependents[id_to_index[dep]].append(i)

    remaining_indegree = indegree.copy()
    queue = deque()
    for i in range(n):
        if remaining_indegree[i] == 0:
            queue.append(i)

    processed = 0
    while queue:
        u = queue.popleft()
        processed += 1
        for v in dependents[u]:
            remaining_indegree[v] -= 1
            if remaining_indegree[v] == 0:
                queue.append(v)

    if processed != n:
        raise ValueError("cycle detected")

    remaining_deps = [len(d) for d in deps]
    ready = []
    for i in range(n):
        if remaining_deps[i] == 0:
            heapq.heappush(ready, (-priorities[i], ids[i], i))

    free_workers = []
    next_worker = 0
    running = []
    actions = []
    scheduled = 0
    time = 0

    while scheduled < n:
        while running and running[0][0] == time:
            end, i, worker = heapq.heappop(running)
            heapq.heappush(free_workers, worker)

            for dependent in dependents[i]:
                remaining_deps[dependent] -= 1
                if remaining_deps[dependent] == 0:
                    heapq.heappush(
                        ready,
                        (-priorities[dependent], ids[dependent], dependent),
                    )

        while ready and (free_workers or next_worker < workers):
            if free_workers:
                worker = heapq.heappop(free_workers)
            else:
                worker = next_worker
                next_worker += 1

            neg_priority, jid, i = heapq.heappop(ready)
            start = time
            end = start + durations[i]

            actions.append({
                "id": jid,
                "start": start,
                "end": end,
                "worker": worker,
            })
            heapq.heappush(running, (end, i, worker))
            scheduled += 1

        if scheduled == n:
            break

        if not running:
            raise ValueError("cannot schedule jobs")

        time = running[0][0]

    return actions

