def schedule_jobs(jobs: list[dict], workers: int) -> list[dict]:
    if not isinstance(workers, int) or isinstance(workers, bool) or workers <= 0:
        raise ValueError("workers must be a positive integer")

    n = len(jobs)
    if n == 0:
        return []

    ids = [None] * n
    durations = [0] * n
    priorities = [0] * n
    deps_lists = [None] * n
    id_to_index = {}

    for i, job in enumerate(jobs):
        if not isinstance(job, dict):
            raise ValueError("job must be a dict")
        try:
            jid = job["id"]
            duration = job["duration"]
            priority = job["priority"]
            deps = job["deps"]
        except KeyError:
            raise ValueError("missing job field")

        if not isinstance(jid, str):
            raise ValueError("job id must be a string")
        if jid in id_to_index:
            raise ValueError("duplicate job id")
        if not isinstance(duration, int) or isinstance(duration, bool) or duration <= 0:
            raise ValueError("duration must be a positive integer")
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be an integer")
        if not isinstance(deps, list):
            raise ValueError("deps must be a list")

        id_to_index[jid] = i
        ids[i] = jid
        durations[i] = duration
        priorities[i] = priority
        deps_lists[i] = deps

    dep_sets = [None] * n
    for i in range(n):
        jid = ids[i]
        ds = set()
        for dep in deps_lists[i]:
            if not isinstance(dep, str):
                raise ValueError("dependency must be a string")
            if dep == jid:
                raise ValueError("self-dependency")
            if dep not in id_to_index:
                raise ValueError("unknown dependency")
            ds.add(dep)
        dep_sets[i] = ds

    dependents = [[] for _ in range(n)]
    indegree = [0] * n

    for i, ds in enumerate(dep_sets):
        indegree[i] = len(ds)
        for dep in ds:
            dependents[id_to_index[dep]].append(i)

    queue = [i for i in range(n) if indegree[i] == 0]
    head = 0
    while head < len(queue):
        i = queue[head]
        head += 1
        for j in dependents[i]:
            indegree[j] -= 1
            if indegree[j] == 0:
                queue.append(j)

