        for dep in deps:
            if not isinstance(dep, str):
                raise ValueError("dependency id must be a string")
            if dep == jid:
                raise ValueError("self-dependency")
            if dep not in ids:
                raise ValueError("unknown dependency")
            unique_deps.add(dep)

        records[jid] = {
