    remaining = {jid: len(records[jid]["deps"]) for jid in ids}
    ready = [(-records[jid]["priority"], jid) for jid in ids if remaining[jid] == 0]
    heapq.heapify(ready)

    worker_count = min(workers, n)
    free = list(range(worker_count))
    heapq.heapify(free)

    running = []
    actions = []
    completed = 0
    current_time = 0

    while completed < n:
        while running and running[0][0] == current_time:
            end, worker, jid = heapq.heappop(running)
            heapq.heappush(free, worker)
            completed += 1
            for dep_jid in dependents[jid]:
                remaining[dep_jid] -= 1
