import heapq


def run_cache(capacity: int, operations: list[dict]) -> list:
    entries = OrderedDict()  # key -> (value, expires_at), LRU-to-MRU order
    expiry_heap = []         # (expires_at, key), possibly with stale records
    results = []
    cap = capacity

    def purge(t: int) -> None:
        while expiry_heap and expiry_heap[0][0] <= t:
            expires_at, key = heapq.heappop(expiry_heap)
            item = entries.get(key)
            if item is not None and item[1] == expires_at:
                del entries[key]

    def evict() -> None:
        while len(entries) > cap:
            entries.popitem(last=False)

    for op in operations:
        t = op["t"]
        purge(t)

        name = op["op"]

        if name == "put":
            key = op["key"]
            value = op["value"]
            ttl = op["ttl"]

            if ttl <= 0 or cap == 0:
                if key in entries:
                    del entries[key]
                results.append(None)
                continue

            expires_at = t + ttl
            entries[key] = (value, expires_at)
            entries.move_to_end(key)
            heapq.heappush(expiry_heap, (expires_at, key))
            evict()
            results.append(None)

        elif name == "get":
            key = op["key"]
            item = entries.get(key)
            if item is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(item[0])

        elif name == "delete":
            key = op["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)

        elif name == "items":
            results.append([[key, value] for key, (value, _) in entries.items()])

        elif name == "resize":
            cap = op["capacity"]
            evict()
            results.append(None)

        else:
            results.append(None)

    return results

