            kind, val = tokens[ti]
            if kind == 'q':
                ti += 1
                si += 1
                continue
            if kind == 'lit' and val == s[si]:
                ti += 1
                si += 1
                continue
            if kind == 'star':
                star_ti = ti
                star_si = si
                ti += 1
                continue

        if star_ti != -1:
            star_si += 1
            si = star_si
            ti = star_ti + 1
        else:
            return False

    while ti < nt and tokens[ti][0] == 'star':
        ti += 1
    return ti == nt


